<?php
namespace WPKit\SiteDoctor\Scanners; use WPKit\SiteDoctor\{SiteDoctorIssue,SiteDoctorScanner}; if(!defined('ABSPATH'))exit;
final class MobileScanner implements SiteDoctorScanner{public function id():string{return 'mobile';}public function label():string{return 'Mobile';}public function scan():array{$o=[];$r=wp_safe_remote_get(home_url('/'),['timeout'=>8]);if(is_wp_error($r))return $o;$h=wp_remote_retrieve_body($r);if(!preg_match('/<meta[^>]+name=["\']viewport["\']/i',$h))$o[]=$this->i('missing-viewport','mobile','high','safe','Missing mobile viewport','No viewport meta tag was detected on the homepage.','Ensure the active theme/builder outputs a responsive viewport.');return $o;}private function i($id,$c,$s,$r,$t,$d,$rec){return new SiteDoctorIssue(['id'=>$id,'category'=>$c,'severity'=>$s,'risk'=>$r,'title'=>$t,'description'=>$d,'recommendation'=>$rec]);}}
